// Assemble all partial outputs into the final lesson plan JSON
const input = $normalize-2.output;
const analysis = $analyze-4.output;
const lessonFlow = $activities-6.output;
const worksheet = $worksheet-7.output;
const practice = $practice-8.output;
const glossary = $glossary-9.output;

const result = {
  schemaVersion: 'lesson-plan.v0',
  title: analysis.title || `${input.gradeBand} ${input.subject || ''}教案`,
  summary: analysis.summary || '',
  context: {
    gradeBand: input.gradeBand,
    durationMinutes: input.durationMinutes,
    courseTitle: input.courseTitle || '',
    lessonTitle: input.lessonTitle || ''
  },
  objectives: analysis.objectives || [],
  keyPoints: analysis.keyPoints || [],
  difficulties: analysis.difficulties || [],
  prerequisites: analysis.prerequisites || [],
  lessonFlow: lessonFlow || [],
  differentiation: analysis.differentiation || { support: [], extension: [] },
  worksheetDraft: worksheet || undefined,
  practiceDraft: practice || undefined,
  glossary: glossary || [],
  resourceSuggestions: analysis.resourceSuggestions || [],
  risks: analysis.risks || [],
  teacherReviewChecklist: [
    '教学目标是否可观察、可评估？',
    '课堂流程时间分配是否合理？',
    '师生活动是否与目标一一对应？',
    '是否包含听、说、读、写适当组合？',
    '差异化支持是否适切？',
    '练习草稿是否需要调整难度？',
    '术语释义是否准确？',
    '是否存在文化敏感内容需修改？'
  ]
};

// Remove undefined fields
Object.keys(result).forEach(k => result[k] === undefined && delete result[k]);

return JSON.stringify(result);

// Deterministic JSON Schema validation
const Ajv = require('ajv');
const schema = require('../schemas/lesson-plan-output.schema.json');

const ajv = new Ajv({ allErrors: true, strict: true });
const validate = ajv.compile(schema);

let parsed;
try {
  parsed = JSON.parse($assemble-10.output);
} catch (e) {
  return JSON.stringify({
    valid: false,
    error: 'OUTPUT_SCHEMA_INVALID',
    details: `JSON parse error: ${e.message}`
  });
}

const valid = validate(parsed);

if (valid) {
  // Additional business rules
  const totalMinutes = (parsed.lessonFlow || []).reduce((sum, s) => sum + (s.minutes || 0), 0);
  const targetMinutes = parsed.context?.durationMinutes || 40;
  const minuteDelta = Math.abs(totalMinutes - targetMinutes);

  if (minuteDelta > 10) {
    return JSON.stringify({
      valid: false,
      error: 'OUTPUT_SCHEMA_INVALID',
      details: `lessonFlow minutes total ${totalMinutes} differs from durationMinutes ${targetMinutes} by more than 10`
    });
  }

  return JSON.stringify({ valid: true, data: parsed });
} else {
  return JSON.stringify({
    valid: false,
    error: 'OUTPUT_SCHEMA_INVALID',
    details: validate.errors?.map(e => `${e.instancePath} ${e.message}`).join('; ') || 'Unknown schema error'
  });
}

const validation = JSON.parse($validate-11.output);

if (validation.valid) {
  return JSON.stringify({
    status: 'SUCCEEDED',
    data: validation.data
  });
}

// Try retry if available
const retryResult = $retry-12.output;
if (retryResult) {
  try {
    const retryParsed = JSON.parse(retryResult);
    // Re-validate would happen in the backend, not here
    return JSON.stringify({
      status: 'SUCCEEDED',
      data: retryParsed
    });
  } catch (e) {
    return JSON.stringify({
      status: 'OUTPUT_SCHEMA_INVALID',
      error: 'Second attempt also failed schema validation',
      details: e.message
    });
  }
}

return JSON.stringify({
  status: 'OUTPUT_SCHEMA_INVALID',
  error: validation.details || 'Schema validation failed',
  noRetry: true
});
